    const qreal bleed = m_bleedMm * 10.0; const QRectF source = m_canvas->pageRect().adjusted(-bleed, -bleed, bleed, bleed);
    m_canvas->scene()->render(painter, target, source, Qt::IgnoreAspectRatio);
